; không gộp alias hoặc suy ra retry/khóa tài khoản. is_terminal chỉ mô tả kết quả milestone, không điều khiển scheduler. Bổ sung v349 cho agent và danh mục Automation.","status_key":"invalid_parameter","flatform_type":"all","component_type":"campaign_detail","is_default":false,"is_terminal":true,"can_set_manually":false,"is_active":true,"is_delete":false,"sort_order":190}]$desired$::jsonb) AS d(code text,name text,description text,status_key text,flatform_type text,component_type text,is_default boolean,is_terminal boolean,can_set_manually boolean,is_active boolean,is_delete boolean,sort_order integer) JOIN public.auto_status s ON s.code=d.code OR (s.component_type='campaign_detail' AND lower(s.name)=lower(d.name))) THEN RAISE EXCEPTION 'v349 guard: duplicate code/name'; END IF;
